                continue
            counts = {v: 0 for v in base}
            for rad in range(1, 5):
                for rr in range(max(0, r-rad), min(h, r+rad+1)):
                    for cc in range(max(0, c-rad), min(w, c+rad+1)):
                        if abs(rr-r) + abs(cc-c) <= rad and grid[rr][cc] in base:
                            counts[grid[rr][cc]] += 1
                if max(counts.values()) > 0:
